def truncate_number(number: float) -> float:
    """Return the decimal part of a positive floating point number."""
    return number - int(number)

def string_sequence(n: int) -> str:
    """Return a string containing space-delimited numbers starting from 0 upto n inclusive."""
    return ' '.join(str(i) for i in range(n + 1))

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    result = []
    for char in string:
        if char.isupper():
            result.append(char.lower())
        elif char.islower():
            result.append(char.upper())
        else:
            result.append(char)
    return ''.join(result)

def unique(l: list):
    """Return sorted unique elements in a list
    >>> unique([5, 3, 5, 2, 3, 3, 9, 0, 123])
    [0, 2, 3, 5, 9, 123]
    """
    return sorted(set(l))

def fizz_buzz(n: int) -> int:
    """
    Return the number of times the digit 7 appears in integers less than n
    which are divisible by 11 or 13.
    """
    count = 0
    for i in range(1, n):
        if i % 11 == 0 or i % 13 == 0:
            # Count occurrences of digit '7' in i
            for digit in str(i):
                if digit == '7':
                    count += 1
    return count

def incr_list(l: list):
    """Return list with elements incremented by 1."""
    return [x + 1 for x in l]

def correct_bracketing(brackets: str) -> bool:
    """
    Returns True if every opening bracket '(' has a corresponding closing bracket ')'
    in the correct order, otherwise False.
    """
    balance = 0
    for ch in brackets:
        if ch == '(':
            balance += 1
        elif ch == ')':
            balance -= 1
            if balance < 0:
                return False
    return balance == 0

def digitSum(s):
    """
    Returns the sum of the ASCII codes of all uppercase characters in the input string.
    """
    total = 0
    for ch in s:
        if ch.isupper():
            total += ord(ch)
    return total

def search(lst):
    """
    Returns the greatest integer that is greater than zero and has a frequency
    greater than or equal to the value of the integer itself.
    If no such value exists, returns -1.
    """
    # Count frequencies of each integer
    freq = {}
    for x in lst:
        freq[x] = freq.get(x, 0) + 1

    # Find the maximum integer satisfying the condition
    max_val = -1
    for num, count in freq.items():
        if count >= num:
            max_val = max(max_val, num)

    return max_val

def hex_key(num: str) -> int:
    """
    Counts the number of hexadecimal digits in the given string that are prime.
    Prime hexadecimal digits are: 2, 3, 5, 7, B (11), D (13).
    """
    prime_digits = {'2', '3', '5', '7', 'B', 'D'}
    count = 0
    for ch in num:
        if ch in prime_digits:
            count += 1
    return count

def prime_length(string):
    length = len(string)
    if length < 2:
        return False
    for i in range(2, int(length ** 0.5) + 1):
        if length % i == 0:
            return False
    return True

def starts_one_ends(n: int) -> int:
    """
    Return the count of n-digit positive integers that start or end with the digit 1.
    """
    if n == 1:
        return 1
    # For n >= 2: 18 * 10^(n-2)
    return 18 * (10 ** (n - 2))

def add(lst):
    """Given a non-empty list of integers lst. add the even elements that are at odd indices..

    Examples:
        add([4, 2, 6, 7]) ==> 2 
    """
    total = 0
    for i in range(len(lst)):
        if i % 2 == 1 and lst[i] % 2 == 0:
            total += lst[i]
    return total

import math

def skjkasdkd(lst):
    """
    Returns the sum of the digits of the largest prime number in the given list.
    If no prime exists, returns 0.
    """
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(math.isqrt(n))
        for i in range(3, limit + 1, 2):
            if n % i == 0:
                return False
        return True

    max_prime = 0
    for num in lst:
        if is_prime(num) and num > max_prime:
            max_prime = num

    # Sum of digits of max_prime (0 if no prime found)
    return sum(int(d) for d in str(max_prime))

def choose_num(x, y):
    """
    Returns the largest even integer in the inclusive range [x, y].
    If no such number exists, returns -1.
    """
    if x > y:
        return -1
    # Largest even number not exceeding y
    largest_even = y if y % 2 == 0 else y - 1
    if largest_even >= x:
        return largest_even
    else:
        return -1

