def valid_date(date):
    """
    Validates a date string in the format mm-dd-yyyy according to the given rules.
    Returns True if valid, False otherwise.
    """
    # Rule 1: date string must not be empty
    if not date:
        return False

    # Rule 4: format must be mm-dd-yyyy (exactly two hyphens, parts are numeric with correct lengths)
    parts = date.split('-')
    if len(parts) != 3:
        return False

    month_str, day_str, year_str = parts

    # Check that each part is numeric and has the correct length
    if not (month_str.isdigit() and len(month_str) == 2):
        return False
    if not (day_str.isdigit() and len(day_str) == 2):
        return False
    if not (year_str.isdigit() and len(year_str) == 4):
        return False

    # Convert to integers
    month = int(month_str)
    day = int(day_str)
    year = int(year_str)  # year is not used for validation beyond format

    # Rule 3: month must be between 1 and 12
    if month < 1 or month > 12:
        return False

    # Rule 2: day validation based on month
    if month in [1, 3, 5, 7, 8, 10, 12]:
        # 31-day months
        if day < 1 or day > 31:
            return False
    elif month in [4, 6, 9, 11]:
        # 30-day months
        if day < 1 or day > 30:
            return False
    elif month == 2:
        # February: 1-29 (no leap year check)
        if day < 1 or day > 29:
            return False

    # All checks passed
    return True

def split_words(txt):
    '''
    Given a string of words, return a list of words split on whitespace, if no whitespaces exists in the text you
    should split on commas ',' if no commas exists you should return the number of lower-case letters with odd order in the
    alphabet, ord('a') = 0, ord('b') = 1, ... ord('z') = 25
    Examples
    split_words("Hello world!") ➞ ["Hello", "world!"]
    split_words("Hello,world!") ➞ ["Hello", "world!"]
    split_words("abcdef") == 3 
    '''
    # Check for whitespace
    if any(c.isspace() for c in txt):
        return txt.split()
    # Check for commas
    if ',' in txt:
        return txt.split(',')
    # Otherwise count lowercase letters with odd alphabet order
    count = 0
    for c in txt:
        if c.islower():
            # ord('a') = 97, so index = ord(c) - 97
            if (ord(c) - 97) % 2 == 1:
                count += 1
    return count

def largest_smallest_integers(lst):
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''
    max_neg = None
    min_pos = None
    for num in lst:
        if num < 0:
            if max_neg is None or num > max_neg:
                max_neg = num
        elif num > 0:
            if min_pos is None or num < min_pos:
                min_pos = num
    return (max_neg, min_pos)

def compare_one(a, b):
    """
    Create a function that takes integers, floats, or strings representing
    real numbers, and returns the larger variable in its given variable type.
    Return None if the values are equal.
    Note: If a real number is represented as a string, the floating point might be . or ,

    compare_one(1, 2.5) ➞ 2.5
    compare_one(1, "2,3") ➞ "2,3"
    compare_one("5,1", "6") ➞ "6"
    compare_one("1", 1) ➞ None
    """
    def to_float(x):
        if isinstance(x, (int, float)):
            return float(x)
        elif isinstance(x, str):
            # Replace comma with dot for decimal parsing
            return float(x.replace(',', '.'))
        else:
            raise TypeError("Unsupported type")

    a_val = to_float(a)
    b_val = to_float(b)

    if a_val > b_val:
        return a
    elif b_val > a_val:
        return b
    else:
        return None

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if not text:
        return None
    return hashlib.md5(text.encode()).hexdigest()
